use payments::{PaymentClient, SavedCards};

#[tokio::test]
async fn charges_the_default_saved_card() {
    let (client, cards) = sandbox().await;
    let card = cards.default_for(CLIENT).await.unwrap();
    let charge = client.charge(&card.token, 4_200, "USD").await.unwrap();
    assert_eq!(charge.status, Status::Succeeded);
}

#[tokio::test]
async fn a_declined_card_reports_card_declined() {
    let (client, _) = sandbox().await;
    let error = client.charge(DECLINED, 4_200, "USD").await.unwrap_err();
    assert_eq!(error.code(), "card_declined");
}

#[tokio::test]
async fn retries_after_3ds_confirmation() {
    let (client, _) = sandbox().await;
    let pending = client.charge(REQUIRES_3DS, 4_200, "USD").await.unwrap();
    let charge = client.confirm(&pending.id).await.unwrap();
    assert_eq!(charge.status, Status::Succeeded);
}
